contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);
        uint before = c.depositsCount(); if (__ESBMC_reverted()) return;
        c.depositsCount(); if (__ESBMC_reverted()) return;
        uint depositsAfterFirst = c.depositsCount(); if (__ESBMC_reverted()) return;
        c.depositsCount(); if (__ESBMC_reverted()) return;
        uint depositsAfterSecond = c.depositsCount(); if (__ESBMC_reverted()) return;
        c.depositsCount(); if (__ESBMC_reverted()) return;
        uint depositsAfterThird = c.depositsCount(); if (__ESBMC_reverted()) return;
        assert(
            depositsAfterFirst == before &&
            depositsAfterSecond == before &&
            depositsAfterThird == before
        );
    }

    receive() external payable {}
}

