// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 before;
        try c.depositsCount() returns (uint256 __r) { before = __r; } catch { return; }
        try c.depositsCount() {} catch { return; }
        uint256 depositsAfterFirst;
        try c.depositsCount() returns (uint256 __r) { depositsAfterFirst = __r; } catch { return; }
        try c.depositsCount() {} catch { return; }
        uint256 depositsAfterSecond;
        try c.depositsCount() returns (uint256 __r) { depositsAfterSecond = __r; } catch { return; }
        try c.depositsCount() {} catch { return; }
        uint256 depositsAfterThird;
        try c.depositsCount() returns (uint256 __r) { depositsAfterThird = __r; } catch { return; }
        assertTrue(depositsAfterFirst == before &&
            depositsAfterSecond == before &&
            depositsAfterThird == before);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
